#include <array>
#include <cstddef>
#include <vector>
#include <omp.h>

void pixelCounts(std::vector<int> const& image, std::array<size_t, 256> &bins) {
    bins.fill(0);

    const int max_threads = omp_get_max_threads();
    std::vector<std::array<size_t, 256>> local_bins(static_cast<std::size_t>(max_threads));
    for (auto& hist : local_bins) {
        hist.fill(0);
    }

    const std::ptrdiff_t n = static_cast<std::ptrdiff_t>(image.size());

    #pragma omp parallel
    {
        const int tid = omp_get_thread_num();
        auto& my_bins = local_bins[static_cast<std::size_t>(tid)];

        #pragma omp for schedule(static)
        for (std::ptrdiff_t i = 0; i < n; ++i) {
            const int pixel = image[static_cast<std::size_t>(i)];
            if (static_cast<unsigned int>(pixel) < 256u) {
                ++my_bins[static_cast<std::size_t>(pixel)];
            }
        }
    }

    for (const auto& hist : local_bins) {
        for (std::size_t i = 0; i < 256; ++i) {
            bins[i] += hist[i];
        }
    }
}
